begin;
do $$ begin perform set_config('request.jwt.claim.sub',(select id::text from auth.users where lower(email)='dejandrea@gmail.com'),true);end $$;
set local role authenticated;
do $$
declare cash uuid:=gen_random_uuid();bank uuid:=gen_random_uuid();category uuid;method uuid;customer integer;debit uuid;credit uuid;
 req uuid:=gen_random_uuid();receipt uuid:=gen_random_uuid();payment uuid:=gen_random_uuid();allocation uuid:=gen_random_uuid();payable uuid:=gen_random_uuid();negative uuid:=gen_random_uuid();expense uuid:=gen_random_uuid();part uuid;opening uuid;data jsonb;count_before bigint;result jsonb;
begin
 perform public.finance_config('accounts',cash,jsonb_build_object('nome','Fixture cash','tipo','CASH','ativo',true,'saldo_inicial',1000,'data','2026-01-01'));
 perform public.finance_config('accounts',cash,jsonb_build_object('nome','Fixture cash','tipo','CASH','ativo',true,'saldo_inicial',1000,'data','2026-01-01'));
 if (select sum(valor) from public.financial_entries where conta_id=cash)<>1000 then raise exception 'Duplicate opening balance';end if;
 perform public.finance_config('accounts',bank,'{"nome":"Fixture bank","tipo":"BANK","ativo":true}');
 select id into category from public.financial_categories where natureza='EXPENSE' limit 1;
 select id into method from public.financial_payment_methods where tipo='CASH' limit 1;
 insert into public.customers(nome,limite) values('Fixture financial customer',10000) returning codigo_cliente into customer;
 insert into public.customer_ledger(customer_codigo,entry_type,amount) values(customer,'DEBIT',100) returning id into debit;
 insert into public.customer_ledger(customer_codigo,entry_type,amount) values(customer,'CREDIT',20) returning id into credit;
 data:=jsonb_build_object('tipo','ALLOCATION','valor',20,'data','2026-01-02','descricao','Fixture allocation','debito_id',debit,'credito_id',credit);
 perform public.finance_operation(allocation,data);
 if (select total_pendente from public.customers where codigo_cliente=customer)<>80 then raise exception 'Allocation changed customer balance twice';end if;
 if exists(select 1 from public.financial_entries where operation_id=allocation) then raise exception 'Allocation moved money';end if;
 begin perform public.finance_operation(gen_random_uuid(),data);raise exception 'FAIL: overallocated credit';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 data:=jsonb_build_object('tipo','RECEIPT','valor',30,'data','2026-01-03','descricao','Fixture receipt','conta_id',cash,'forma_id',method,'debito_id',debit);
 perform public.finance_operation(receipt,data);perform public.finance_operation(receipt,data);
 if (select total_pendente from public.customers where codigo_cliente=customer)<>50 then raise exception 'Receipt credit incorrect';end if;
 if (select sum(valor) from public.financial_entries where conta_id=cash)<>1030 then raise exception 'Duplicate receipt';end if;
 begin perform public.finance_operation(receipt,data||'{"valor":31}');raise exception 'FAIL: changed request';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 begin perform public.finance_operation(gen_random_uuid(),data||'{"valor":51}');raise exception 'FAIL: overpayment';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 perform public.finance_operation(gen_random_uuid(),data||'{"valor":50}');
 if (select total_pendente from public.customers where codigo_cliente=customer)<>0 then raise exception 'Full receipt did not settle';end if;
 perform public.finance_operation(gen_random_uuid(),jsonb_build_object('tipo','REVERSAL','data','2026-01-04','descricao','Fixture receipt reversal','estorno_de',receipt,'motivo','Fixture correction'));
 if (select total_pendente from public.customers where codigo_cliente=customer)<>30 then raise exception 'Reversal did not restore debt';end if;
 if (select count(*) from public.customer_ledger where customer_codigo=customer)<>5 then raise exception 'Receipt history was deleted';end if;
 begin update public.customer_ledger set amount=200 where id=debit;raise exception 'FAIL: edited settled debit';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 begin delete from public.customer_ledger where financial_operation_id=receipt;raise exception 'FAIL: deleted financial credit';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 data:=jsonb_build_object('fornecedor_nome','Fixture supplier','descricao','Fixture payable','total',100,'categoria_id',category,'parcelas',jsonb_build_array(jsonb_build_object('numero',1,'referencia','1','vencimento','2026-12-01','valor',100)));
 perform public.save_supplier_payable(payable,null,data);
 if (select categoria_id from public.supplier_payables where id=payable) is distinct from category then raise exception 'Payable category missing';end if;
 select id into part from public.supplier_payable_installments where payable_id=payable;
 data:=jsonb_build_object('tipo','PAYMENT','valor',25,'data','2026-01-03','descricao','Fixture payment','conta_id',cash,'forma_id',method,'parcela_id',part,'categoria_id',category);
 perform public.finance_operation(payment,data);
 begin perform public.finance_operation(gen_random_uuid(),data||'{"valor":76}');raise exception 'FAIL: payment over balance';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 begin perform public.save_supplier_payable(payable,null,jsonb_build_object('fornecedor_nome','Fixture supplier','descricao','Edited','total',100,'parcelas',jsonb_build_array(jsonb_build_object('numero',1,'vencimento','2026-12-01','valor',100))),true);raise exception 'FAIL: edited paid payable';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 perform public.finance_operation(gen_random_uuid(),jsonb_build_object('tipo','REVERSAL','data','2026-01-04','descricao','Fixture payment reversal','estorno_de',payment,'motivo','Fixture correction'));
 begin perform public.finance_operation(gen_random_uuid(),jsonb_build_object('tipo','REVERSAL','data','2026-01-04','descricao','Duplicate reversal','estorno_de',payment,'motivo','Fixture correction'));raise exception 'FAIL: second reversal';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 data:=jsonb_build_object('tipo','TRANSFER','valor',100,'data','2026-01-05','descricao','Fixture transfer','conta_id',cash,'destino_id',bank);
 perform public.finance_operation(req,data);perform public.finance_operation(req,data);
 if (select sum(valor) from public.financial_entries where operation_id=req)<>0 or (select count(*) from public.financial_entries where operation_id=req)<>2 then raise exception 'Unbalanced transfer';end if;
 if (select sum(valor) from public.financial_entries where conta_id=cash)<>950 or (select sum(valor) from public.financial_entries where conta_id=bank)<>100 then raise exception 'Incorrect account balances';end if;
 begin perform public.finance_operation(gen_random_uuid(),data||jsonb_build_object('destino_id',cash));raise exception 'FAIL: self transfer';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 begin perform public.finance_operation(gen_random_uuid(),data||jsonb_build_object('data',current_date+2));raise exception 'FAIL: future operation';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 perform public.finance_config('accounts',bank,'{"nome":"Fixture bank","tipo":"BANK","ativo":false}');
 begin perform public.finance_operation(gen_random_uuid(),data);raise exception 'FAIL: inactive account';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 data:=jsonb_build_object('tipo','EXPENSE','valor',10,'data','2026-01-05','descricao','Fixture expense','conta_id',cash,'forma_id',method,'categoria_id',category);
 perform public.finance_operation(expense,data);
 if (select sum(valor) from public.financial_entries where conta_id=cash)<>940 then raise exception 'Manual expense missing';end if;
 begin perform public.finance_operation(gen_random_uuid(),data||jsonb_build_object('tipo','INCOME'));raise exception 'FAIL: incompatible category';exception when raise_exception then if SQLERRM like 'FAIL:%' then raise;end if;end;
 perform public.finance_operation(gen_random_uuid(),jsonb_build_object('tipo','REVERSAL','data','2026-01-05','descricao','Fixture expense reversal','estorno_de',expense,'motivo','Fixture correction'));
 if (select sum(valor) from public.financial_entries where conta_id=cash)<>950 then raise exception 'Expense reversal incorrect';end if;
 perform public.finance_config('accounts',negative,'{"nome":"Fixture negative","tipo":"BANK","ativo":true,"saldo_inicial":-25,"data":"2026-01-01"}');
 if (select sum(valor) from public.financial_entries where conta_id=negative)<>-25 then raise exception 'Negative opening incorrect';end if;
 select id into opening from public.financial_operations where conta_id=negative and tipo='OPENING';
 perform public.finance_operation(gen_random_uuid(),jsonb_build_object('tipo','REVERSAL','data','2026-01-05','descricao','Fixture opening reversal','estorno_de',opening,'motivo','Fixture correction'));
 if (select sum(valor) from public.financial_entries where conta_id=negative)<>0 then raise exception 'Negative opening reversal incorrect';end if;
 perform public.finance_operation(gen_random_uuid(),jsonb_build_object('tipo','REVERSAL','data','2026-01-05','descricao','Fixture allocation reversal','estorno_de',allocation,'motivo','Fixture correction'));
 if (select total_pendente from public.customers where codigo_cliente=customer)<>30 then raise exception 'Allocation reversal changed customer balance';end if;
 begin update public.financial_entries set valor=999 where conta_id=cash;raise exception 'FAIL: direct entry update';exception when insufficient_privilege then null;end;
 begin delete from public.financial_operations where id=receipt;raise exception 'FAIL: delete operation';exception when insufficient_privilege then null;end;
end $$;
reset role;
-- Role change is uncommitted and rolled back; other sessions continue to see the original role.
update app_private.account_directory d set role='OPERATOR' from public.app_profiles p where p.account_id=d.id and p.auth_user_id=auth.uid();
set local role authenticated;
do $$ declare cash uuid;method uuid;category uuid;begin
 if app_private.app_role()<>'OPERATOR' then raise exception 'Operator fixture not active';end if;
 begin perform public.finance_config('accounts',gen_random_uuid(),'{"nome":"Denied","tipo":"CASH","ativo":true}');raise exception 'FAIL: operator config';exception when insufficient_privilege then null;end;
 begin perform public.finance_operation(gen_random_uuid(),jsonb_build_object('tipo','REVERSAL','data','2026-01-05','descricao','Denied reversal','motivo','Denied'));raise exception 'FAIL: operator reversal';exception when insufficient_privilege then null;end;
 select id into cash from public.financial_accounts where nome='Fixture cash';
 select id into method from public.financial_payment_methods where tipo='CASH' limit 1;
 select id into category from public.financial_categories where natureza='INCOME' limit 1;
 perform public.finance_operation(gen_random_uuid(),jsonb_build_object('tipo','INCOME','valor',1,'data','2026-01-05','descricao','Operator income fixture','conta_id',cash,'forma_id',method,'categoria_id',category));
end $$;
reset role;
do $$ begin perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000000',true);end $$;
set local role authenticated;
do $$ begin
 if exists(select 1 from public.financial_operations) or exists(select 1 from public.financial_accounts) then raise exception 'Unauthorized financial read';end if;
 begin perform public.finance_operation(gen_random_uuid(),'{}');raise exception 'FAIL: unauthorized movement';exception when insufficient_privilege then null;end;
 begin perform public.finance_config('accounts',gen_random_uuid(),'{}');raise exception 'FAIL: unauthorized config';exception when insufficient_privilege then null;end;
end $$;
reset role;
set local role anon;
do $$ begin
 begin perform public.finance_operation(gen_random_uuid(),'{}');raise exception 'FAIL: anon RPC';exception when insufficient_privilege then null;end;
 begin perform 1 from public.financial_entries;raise exception 'FAIL: anon read';exception when insufficient_privilege then null;end;
end $$;
reset role;
rollback;
select 'Financial foundation fixtures passed; no fixture data persisted.' as resultado;
